// Inversão de controlo: confiamos que "apiInstavel" invoca
// o callback exatamente uma vez. Se tiver um bug, nada o impede
// de o chamar mais do que uma vez.
function apiInstavel(callback) {
  callback(null, "primeira resposta");
  callback(null, "segunda resposta"); // nunca deveria acontecer
}

let jaProcessado = false;

apiInstavel((erro, resposta) => {
  if (jaProcessado) {
    console.error("O callback foi invocado mais do que uma vez!");
    return;
  }
  jaProcessado = true;
  console.log("Resposta:", resposta);
});

