function validarIdade(idade, callback) {
  setTimeout(() => {
    if (typeof idade !== "number" || Number.isNaN(idade)) {
      callback(new Error("idade deve ser um número"));
      return;
    }
    if (idade >= 18) {
      callback(null, "maior de idade");
    } else {
      callback(null, "menor de idade");
    }
  }, 300);
}

