function buscarTudoEmParalelo(callback) {
  const ids = [1, 2, 3];
  const resultados = new Array(ids.length);
  let concluidos = 0;
  let falhou = false;

  ids.forEach((id, indice) => {
    buscarProduto(id, (erro, produto) => {
      if (falhou) {
        return; // callback final já foi chamado com erro, ignorar respostas tardias
      }
      if (erro) {
        falhou = true;
        callback(erro);
        return;
      }
      resultados[indice] = produto;
      concluidos++;
      if (concluidos === ids.length) {
        callback(null, resultados);
      }
    });
  });
}

buscarTudoEmParalelo((erro, produtos) => {
  if (erro) {
    console.error("Falha ao buscar produtos:", erro.message);
    return;
  }
  console.log(produtos);
});
